import{_ as a,c as n,o as r,ah as o}from"./chunks/framework.DaDXF32t.js";const u=JSON.parse('{"title":"UV Post-Synchronization Cache Cleanup Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-03-uv-post-sync-cache-cleanup-design.md","filePath":"superpowers/specs/2026-08-03-uv-post-sync-cache-cleanup-design.md","lastUpdated":1785749755000}'),t={name:"superpowers/specs/2026-08-03-uv-post-sync-cache-cleanup-design.md"};function i(s,e,c,l,d,h){return r(),n("div",null,e[0]||(e[0]=[o('<h1 id="uv-post-synchronization-cache-cleanup-design" tabindex="-1">UV Post-Synchronization Cache Cleanup Design <a class="header-anchor" href="#uv-post-synchronization-cache-cleanup-design" aria-label="Permalink to “UV Post-Synchronization Cache Cleanup Design”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Keep every UV-related file inside the installation root while avoiding retained download caches after a dependency resolution and synchronization completes successfully.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to “Behavior”">​</a></h2><p><code>sync_portable_uv</code> will clear disposable cache data only after the current run has successfully completed both <code>uv pip compile</code> and <code>uv pip sync</code> and has durably written <code>.baas-installer/dependencies-v1.sha256</code>.</p><p>The cleanup removes these installation-local directories:</p><ul><li><code>toolkit/uv/cache</code></li><li><code>toolkit/uv/python-cache</code></li><li><code>toolkit/uv/xdg/cache</code></li><li><code>tmp/uv</code></li></ul><p>It preserves the portable UV executable, installed CPython, <code>.venv</code>, source-ranking data, credentials/configuration, compiled requirements, and dependency SHA stamp.</p><p>When the dependency SHA is unchanged, UV remains fully skipped and existing cache directories are not touched. If resolution or synchronization fails, caches are retained so the retry can reuse already downloaded data.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to “Error Handling”">​</a></h2><p>Cleanup is a required final stage of a real dependency synchronization. Failure to remove any selected cache directory returns an installation error that identifies the affected path. Successfully removed directories are not recreated at the end of the run; UV will recreate them when a future dependency change requires another synchronization.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to “Tests”">​</a></h2><p>Automated tests will verify:</p><ol><li>Successful compile, sync, and stamp persistence remove all four cache directories while preserving UV, CPython, <code>.venv</code>, ranking state, and the stamp.</li><li>A dependency SHA cache hit executes no UV commands and does not alter pre-existing cache contents.</li><li>Compile or sync failure does not clear caches.</li><li>Cleanup failure is reported as an error where the platform permits a deterministic failure fixture.</li></ol><p>The normal Release suite, a fresh Windows installation, a second no-op run, and rename validation remain required before completion.</p>',15)]))}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
